-- Stored Procedure: update_inventory

CREATE OR ALTER PROCEDURE update_inventory (
    @order_id INT
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Add a transaction for atomicity
    BEGIN TRANSACTION;

    -- Update inventory levels based on incoming orders
    UPDATE i
    SET stock_level = stock_level + oi.quantity
    FROM inventory i
    INNER JOIN orders_items oi ON i.product_id = oi.product_id
    WHERE i.order_id = @order_id;

    -- Check for negative stock and handle accordingly (e.g., log, prevent order fulfillment)
    -- This can be done within the same UPDATE statement or in a separate query.
    -- Example:
    -- DELETE FROM inventory WHERE stock_level < 0;

    -- Add a locking hint to prevent deadlocks
    OPTION (MAXDOP 1, LOCK_ESCALATION = TABLE);

    -- Index Recommendation:
    -- Create a non-clustered index on the 'inventory' table to speed up the join.
    -- Consider an index on (product_id, order_id)
    CREATE INDEX IX_Inventory_ProductOrder ON inventory (product_id, order_id);

    COMMIT TRANSACTION;
END;
GO
